            display: none;
        }

        .v2-child-body.show {
            display: block;
        }

        .people-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 16px;
            cursor: pointer;
            border-bottom: 1px solid #eee;
            align-items: center;

            cursor: pointer;
            background-color: #fff;
            margin: 00;
            overflow: hidden;
        }

        .people-row:hover {
            background: #f7f9fc;
        }

        .people-scheduler {
            visibility: hidden;
            color: #4e86c7;
            cursor: pointer;
        }

        .people-row:hover .people-scheduler {
            visibility: visible;
        }
    </style>
