        }

        /* Make ONLY the dropdown options white */
        .inbox-user-select option {
            background: #ffffff !important;
            color: #000000 !important;
        }

        /* Highlight on hover / selected option */
        .inbox-user-select option:checked,
        .inbox-user-select option:hover {
            background: #f3f6fb !important;
            color: #000000 !important;
        }

        .filter-group {
            position: relative;
        }

        .group-btn {
            display: flex;
            align-items: center;
            gap: 6px;
            background: #f3f6fb;
            border-radius: 8px;
            padding: 6px 12px;
            border: none;
            cursor: pointer;
            font-size: 13px;
            width: 100px;
        }

        .group-btn:hover {
            background: #e1e7f5;
        }

        .group-btn .arrow {
            font-size: 16px;
            transition: .2s;
        }

        .filter-group.open .arrow {
            transform: rotate(180deg);
        }

        .group-menu {
            position: absolute;
            top: 115%;
            left: 0;
            background: #fff;
            border-radius: 10px;
            box-shadow: 0 10px 25px rgba(0, 0, 0, .15);
            padding: 6px;
            display: none;
            z-index: 1000;
            min-width: 210px;
        }

        .filter-group.open .group-menu {
            display: block;
        }

        .group-menu .icon-filter {
            width: 100%;
            justify-content: flex-start;
            border-radius: 6px;
        }

        .group-menu .icon-filter:hover {
