        .deep-search-highlight {
            animation: highlightFlash 1s ease-in-out 3;
            background: #fff3cd;
            border: 1px solid #ffc107;
        }

        @keyframes highlightFlash {
            0% {
                background: #fff3cd;
            }

            50% {
                background: #ffe69c;
            }

            100% {
                background: #fff3cd;
            }
        }

        .custom-header {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* button style */
        .hdr-btn {
            padding: 6px 14px;
            background: #4e86c7;
            border-radius: 5px;
            cursor: pointer;
            font-size: 13px;
            font-weight: 500;
            white-space: nowrap;
            color: white;
        }

        .hdr-btn.active {
            background: #4e86c7;
            color: black;
        }

        /* fix select alignment */
        .inbox-user-switcher {
            display: flex;
            align-items: center;
        }

        /* dropdown */
        .hdr-dropdown {
            position: relative;
            width: 180px;
        }

        .dropdown-menu {
            position: absolute;
            top: 110%;
            left: 0;
            background: #fff;
            border-radius: 8px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
            display: none;
            min-width: 180px;
            z-index: 9999;
        }

        .dropdown-item {
            padding: 8px 12px;
            cursor: pointer;
        }

        .dropdown-item:hover {
            background: #f3f6fb;
        }

        /* show dropdown */
        .hdr-dropdown.open .dropdown-menu {
            display: block;
        }

        .dots-menu {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 36px;
            height: 36px;
            padding: 0;
            border-radius: 50%;
        }

        .dots-menu .material-icons {
            font-size: 20px;
        }

        .dropdown-submenu {
            position: relative;
        }

        .dropdown-submenu .submenu {
            display: none;
            position: absolute;
            left: 100%;
            top: 0;
            min-width: 180px;
            background: #fff;
            border-radius: 6px;
            box-shadow: 0 6px 20px rgba(0, 0, 0, 0.15);
        }

        .dropdown-submenu:hover .submenu {
            display: block;
        }

        .submenu-toggle {
            display: flex;
            justify-content: space-between;
        }

        .accordion-header {
            padding: 8px 12px;
            background: #f3f6fb;
            cursor: pointer;
            border-bottom: 1px solid #ddd;
            font-weight: 500;
            display: flex;
            justify-content: space-between;
        }

        .accordion-body {
            padding: 8px 12px;
            background: #fff;
        }

        .task-item {
            padding: 4px 0;
            font-size: 13px;
            border-bottom: 1px dashed #eee;
        }

        .search-highlight {
            border: 2px solid #90ee90;
            /* light green */
            border-radius: 6px;
            background: #f0fff0;
        }

        /* Target the actual header element */
        .user-main {
            position: sticky !important;
            top: 0;
            z-index: 1050;
            /* Stays above task cards */
            background: white;
        }

        .submenu-toggle {
            pointer-events: none;
            /* ❌ disable click */
            cursor: default;
            /* normal cursor */
            font-weight: 600;
            /* looks like header */
        }

        .stepper-horizontal li:not(:first-child)::before {
