    $('.nav-link').on('click', function (e) {
      e.preventDefault();

      $('.module-header').removeClass('Tab-CActive');

      const target = $(this).data('target');
      $(target).addClass('Tab-CActive');
      const offset = 50; // adjust based on tab/header height

      $('html, body').animate({
        scrollTop: $(target).offset().top - offset
      }, 500);
    });

    $('.nav-link').on('click', function () {
      $('.nav-link').removeClass('active');
      $(this).addClass('active');
    });



  </script>

  <script>
    //        dynamically add readmore btn if content exceeds 6 lines



    $(document).ready(function () {

      $('.desc').each(function () {

        var $desc = $(this);

        // Get line height
        var lineHeight = parseFloat($desc.css('line-height'));

        // If line-height is normal, calculate it
        if (isNaN(lineHeight)) {
          lineHeight = parseFloat($desc.css('font-size')) * 1.2;
        }

        var maxHeight = lineHeight * 3;

        // Check if content exceeds 6 lines
        if ($desc[0].scrollHeight > maxHeight + 4) {

          $desc.after('<button class="read-more-btn">Read More</button>');
        }
      });

      $(document).on('click', '.read-more-btn', function () {

        var $btn = $(this);
        var $desc = $btn.prev('.desc');

        if ($desc.hasClass('expanded')) {

          $desc.removeClass('expanded');
          $btn.text('Read More');

        } else {

          $desc.addClass('expanded');
          $btn.text('Read Less');
        }
      });



    });





  </script>

  <script>

    document.querySelectorAll(".Quick-Links")
      .forEach(wrapper => {

        const carousel =
          wrapper.querySelector(".nav-pills");

        const leftBtn =
          wrapper.querySelector(".btn-left");

        const rightBtn =
          wrapper.querySelector(".btn-right");

        const cards =
          carousel.querySelectorAll(".nav-pills");
        if (!rightBtn || !leftBtn || cards) {
          console.warn("Carousel buttons not found");
          return;
        }


        function updateButtons() {

          const maxScroll =
            carousel.scrollWidth -
            carousel.clientWidth;

          leftBtn.classList.toggle(
            "hidden",
            carousel.scrollLeft <= 5
          );

          rightBtn.classList.toggle(
            "hidden",
            carousel.scrollLeft >= maxScroll - 5
          );
        }


        function scrollNext() {

          const current =
            carousel.scrollLeft;

          for (let card of cards) {

            if (card.offsetLeft > current + 10) {

              carousel.scrollTo({
                left: card.offsetLeft,
                behavior: "smooth"
              });

              break;
            }
          }
        }



        function scrollPrev() {

          const current =
            carousel.scrollLeft;

          for (let i = cards.length - 1; i >= 0; i--) {

            if (cards[i].offsetLeft < current - 10) {

              carousel.scrollTo({
                left: cards[i].offsetLeft,
                behavior: "smooth"
              });

              break;
            }

          }
        }



        rightBtn.addEventListener(
          "click",
          scrollNext
        );


        leftBtn.addEventListener(
          "click",
          scrollPrev
        );


        carousel.addEventListener(
          "scroll",
          updateButtons
        );

        window.addEventListener(
          "resize",
          updateButtons
        );

        updateButtons();

      });
  </script>


