    async function loadInboxSummary() {

      $("#InboxCards").empty();
      debugger;
      parent.ShowDimmer(true);

      const sections = [
        // { key: "tasks", label: "Tasks", ds: "DS_AxpertInbox_V2" },
        { key: "pending", label: "Approvals pending with me", ds: "DS_PendingApprovals" },
        { key: "pending", label: "Approvals requested by me", ds: "REQUESTEDBYME" },
        // { key: "notifications", label: "Notifications", ds: "DS_Notifications" },
        { key: "Reminders", label: "Reminders", ds: "DS_Reminders" },
        { key: "Escalations", label: "Escalations", ds: "DS_Escalations" },
        { key: "completed", label: "Completed", ds: "DS_Completed" },
        // { key: "people", label: "People", ds: "DS_People" },
        // { key: "groups", label: "Groups", ds: "DS_Groups" }
      ];

      for (const sec of sections) {

        const params = {
          adsNames: [sec.ds],
          props: {
            pageno: 1,
            pagesize: 0
          },
          sqlParams: {
            uname: parent.mainUserName,
            searchtext: ""
          }
        };
        debugger;
        parent.GetDataFromAxList(params, function (response) {
          debugger;
          try {

            const raw =
              typeof response === "string"
                ? response
                : typeof response.d === "string"
                  ? response.d
                  : JSON.stringify(response.d || response);

            const parsed =
              JSON.parse(raw);

            const result =
              typeof parsed.d === "string"
                ? JSON.parse(parsed.d)
                : parsed;

            const ds =
              result.result.data[0];

            const count =
              ds.totalcount ||
              ds.recordcount ||
              ds.totalrows ||
              (ds.data ? ds.data.length : 0);

            $("#InboxCards").append(createInboxCard(sec.label, count, sec.key));
            setTimeout(() => {
              parent.ShowDimmer(false);
            }, 0)
          }
          catch (e) {

            $("#InboxCards").append(createInboxCard(sec.label, 0, sec.key));
            parent.ShowDimmer(false);

          }

        });

      }

    }

    function createInboxCard(title, count, key) {

      return `
        <div class="Aggregation-Item-wrap">
            <a href="javascript:void(0)"
               class="Aggregation-item inboxCard"
               data-section="${key}">

                <div class="Aggregation-icon">
                    <span class="material-icons material-icons-style material-icons-2">
                        mark_email_unread
                    </span>
                </div>

                <div class="Aggregation-content">
                    <h6 class="subtitle">${title}</h6>
                    <h4 class="value">${count}</h4>
                </div>

            </a>
        </div>`;
    }

