    function loadUserAccess() {

      var params = {
        adsNames: ["ds_custom_useraccess"],
        props: {
          pageno: 1,
          pagesize: 0
        },
        sqlParams: {
          puser: parent.mainUserName
        }
      };
      debugger;
      parent.GetDataFromAxList(
        params,
        function (response) {

          console.log(response);

          applyUserAccess(response);

        },
        function (error) {

          console.log(error);

        }
      );
    }
    function applyUserAccess(response) {

      // Parse response.d
      var parsed = JSON.parse(response);

      var accessList = parsed.result.data[0].data || [];

      // Use sname instead of transid
      var userTransIds = accessList.map(function (x) {
        return (x.sname || "").toLowerCase().trim();
      });

      console.log("User Access:", userTransIds);

      $(".Module-Child-Wrapper").hide();

      $(".Module-Child-Wrapper").each(function () {

        var $title = $(this).find(".title").first();

        var transid = ($title.attr("data-transid") || "")
          .toLowerCase()
          .trim();

        // Existing logic for forms
        if (transid && userTransIds.includes(transid)) {
          $(this).show();
          return;
        }

        // Special case for pages like Chart of Accounts
        var transtype = ($title.attr("data-transtype") || "")
          .toLowerCase()
          .trim();

        if (transtype === "p") {

          var caption = $title.text().trim().toLowerCase();

          var hasAccess = accessList.some(function (x) {
            return (x.stype || "").toLowerCase() === "p" &&
              (x.caption || "").trim().toLowerCase() === caption;
          });

          if (hasAccess) {
            $(this).show();
          }
        }

      });

      // Hide empty modules
      $(".card-ui.Module-Wrapper").each(function () {

        var $module = $(this);

        // --- FIXED: Skip Inbox, Account Receivables, and Account Payable sections explicitly ---
        if ($module.find("#Inbox").length) // ||
        // $module.find("#AccountReceivables").length ||
        // $module.find("#AccountPayable").length ||
        // $module.find("#ChartOfAccounts").length) 
        {
          $module.show(); // Ensure they remain visible

          var moduleId = $module.find(".Module-Parent .module-header:first").attr("id");
          if (moduleId) {
            $('.nav-link[data-target="#' + moduleId + '"]').show();
          }
          return true; // Continue to next loop
        }

        var visibleChildren = $module.find(".Module-Child-Wrapper:visible").length;

        if (visibleChildren === 0) {

          // Hide complete section including header, description and cards
          $module.hide();

          // Hide corresponding tab
          var moduleId = $module
            .find(".Module-Parent .module-header:first")
            .attr("id");

          if (moduleId) {
            $('.nav-link[data-target="#' + moduleId + '"]').hide();
          }
        }
        else {

          // Ensure section and tab are visible if at least one child is visible
          $module.show();

          var moduleId = $module
            .find(".Module-Parent .module-header:first")
            .attr("id");

          if (moduleId) {
            $('.nav-link[data-target="#' + moduleId + '"]').show();
          }
        }
      });

      $(".Quick-Links").removeClass("d-none");
    }



