      let btn = $(e).find("button")[0];

      if (btn) {
        // If already clicked and locked out, exit early
        if (btn.style.pointerEvents === "none") {
          return false;
        }
        // Lock out the button immediately to avoid duplicate firing
        btn.style.pointerEvents = "none";
      }

      if (e.hasClass("linkGray")) {
        // Reset block and return if button shouldn't navigate
        if (btn) btn.style.pointerEvents = "auto";
        return false;
      }

      // 1️⃣ Safe Array Checks before dropping elements
      if (appLinkHistoryLabel.length > 0) appLinkHistoryLabel.pop();
      if (appLinkHistory.length > 0) {
        appLinkHistory.pop();
      }

      if (isMobile && 1 == appLinkHistory.length) {
        console.log("axm_mainpageloaded");
      }

      // 2️⃣ Force clear pointer lock right before navigation updates
      if (btn) {
        setTimeout(() => {
          btn.style.pointerEvents = "auto";
        }, 300); // 300ms fallback timeout to free click locks
      }

      updateLinks(e, "prev");
    }



    // 1. Function to open Tstruct (Handles both standard forms and entity views)
    function open_tstruct(transid, mode) {
      debugger
      var url = "";
      if (mode === "create") {
        url = "../../aspx/tstruct.aspx?transid=" + encodeURIComponent(transid) + "&hltype=open&createaxiflag=true&dummyload=false&hdnbElapsTime=0";
      } else if (mode === "view") {
        url = "../../aspx/Entity.aspx?tstid=" + encodeURIComponent(transid) + "&hdnbElapsTime=0";
      } else {
        url = "../../aspx/tstruct.aspx?transid=" + encodeURIComponent(transid) + "&act=load";
      }
      navigateToUrl(url);
    }

    // 2. Function to open Iview
    function openIview(ivname) {
      var url = "../../aspx/iview.aspx?ivname=" + encodeURIComponent(ivname) + "&hdnbElapsTime=0";
      navigateToUrl(url);
    }

    // 3. Function to open ADS Smartview
    function openAds(adsParam) {
      var url = "/AxpertPlugins/Axi_Beta/HTMLPages/Smartview.html?ads=" + encodeURIComponent(adsParam) + "&load=1769601086182&filter=eyJmaWx0ZXJzIjpbXX0=&hdnbElapsTime=0";
      navigateToUrl(url);
    }

    // Global uniform navigation execution function
    function navigateToUrl(url) {
      console.log("Navigating link to URL:", url);
      // Check if Application Shell's LoadUrl method is available inside the iframe framework
      if (typeof LoadUrl === "function") {
        LoadUrl(url);
      } else if (window.parent && typeof window.parent.LoadUrl === "function") {
        window.parent.LoadUrl(url);
      } else {
        window.location.href = url;
      }
    }



    $(document).ready(function () {
      parent.ShowDimmer(true);

      loadInboxSummary();
      loadUserAccess();



      $(document).on('click', '.Action-Btns button, .Action-Btns a, button.navigate, a[data-transid]', function (e) {
        e.preventDefault();

        var $el = $(this);
        var transid = $el.attr('data-transid') || '';
        var transtype = $el.attr('data-transtype') || '';
        var elementText = $el.text().trim().toLowerCase();

        // FIX: Fallback sequence to discover transid from headers if not specified directly on the button/link
        if (!transid) {
          // Look into the closest Child wrapper, Module Parent, or card container
          var $container = $el.closest('.Module-Child-Wrapper, .Module-Parent, .card-ui');
          var $titleEl = $container.find('.module-header .title');

          transid = $titleEl.attr('data-transid') || '';
          transtype = transtype || $titleEl.attr('data-transtype') || '';
        }

        // Automatically determine standard transactional type if not explicitly provided
        if (!transtype) {
          if (elementText.indexOf('create') > -1) {
            transtype = 'tstruct-create';
          } else if (elementText.indexOf('view') > -1) {
            transtype = 'tstruct-view';
          }
        }

        // Safeguard check against unconfigured/empty dummy actions
        if (!transid && transtype !== 'ads') {
          console.warn("Navigation halted: 'data-transid' attribute missing or empty.", $el);
          return;
        }

        // Core Router Routing Mechanism
        switch (transtype.toLowerCase()) {
          case 'iview':
            openIview(transid);
            break;
          case 'ads':
            // For ADS, fallback to link/button text suffix if transid is explicitly blank
            var adsName = $el.text().trim();
            openAds(adsName);
            break;
          case 'tstruct-create':
            open_tstruct(transid, 'create');
            break;
          case 'tstruct-view':
            open_tstruct(transid, 'view');
            break;
          default:
            // Default fallback handler
            open_tstruct(transid, 'create');
            break;
        }
        return false;
      });

    });
  </script>

